hints:
for each worker:
  initialize a frequency array of size 1440 to 0
  for each time of the worker:
    increment frequency at that minute
  maintain a count of accesses in a 61-minute window
  slide the window from 0 to 1439:
    if count >= 3:
      add worker to alerts and break

code.cpp:
class Solution {
public:
    vector<string> alertNames(vector<string>& keyName, vector<string>& keyTime) {
        unordered_map<string, vector<int>> workerTimes;
        for (int i = 0; i < keyName.size(); i++) {
            int minutes = (keyTime[i][0] - '0') * 600 + (keyTime[i][1] - '0') * 60 + 
                          (keyTime[i][3] - '0') * 10 + (keyTime[i][4] - '0');
            workerTimes[keyName[i]].push_back(minutes);
        }

        vector<string> ans;
        for (auto& pair : workerTimes) {
            vector<int>& times = pair.second;
            int freq[1440] = {0};
            for (int t : times) {
                freq[t]++;
            }

            int count = 0;
            for (int i = 0; i < 61; i++) {
                count += freq[i];
            }
            if (count >= 3) {
                ans.push_back(pair.first);
                continue;
            }

            bool alert = false;
            for (int i = 61; i < 1440; i++) {
                count += freq[i];
                count -= freq[i - 61];
                if (count >= 3) {
                    alert = true;
                    break;
                }
            }
            if (alert) {
                ans.push_back(pair.first);
            }
        }

        sort(ans.begin(), ans.end());
        return ans;
    }
};
